package cn.crhistory.player;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import java.io.*;import org.json.JSONObject;
/** 同包私有入口，资源已经由主进程准备，不提供文件导入或账户登录。 */
public final class ReplayEntry extends Activity {
 private boolean closed,handedOff;
 protected void attachBaseContext(Context base){super.attachBaseContext(ExternalAssets.engineContext(base));}
 public File getFilesDir(){return ExternalAssets.files(this);}
 public void onCreate(Bundle b){super.onCreate(b);try{ReplayRun.entered(this,getIntent().getStringExtra("replay_run"));}catch(Exception ignored){}TextView status=new TextView(this);status.setText("正在打开回放…");status.setPadding(32,64,32,32);setContentView(status);new Thread(()->{try{try(InputStream in=new FileInputStream(new File(getFilesDir(),"source.json"));ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new IOException("回放文件无法读取");byte[] block=new byte[8192];int n;while((n=in.read(block))!=-1){if(out.size()+n>16*1024*1024)throw new IOException("回放文件过大");out.write(block,0,n);}JSONObject replay=new JSONObject(out.toString("UTF-8"));String viewer=getIntent().getStringExtra("viewer_account");if(viewer!=null)replay.put("_viewerAccount",viewer);JSONObject catalog=null;ReplayBootstrap.validate(replay,catalog);ExternalAssets.selectContent(this,ReplayBootstrap.contentRules(replay,catalog),ReplayCompatibility.find(catalog,replay));File catalogFile=new File(getFilesDir(),"replay-catalog.json");if(catalog!=null)java.nio.file.Files.write(catalogFile.toPath(),catalog.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));else catalogFile.delete();new File(getFilesDir(),"playback-result.json").delete();File tmp=new File(getFilesDir(),"replay.json.tmp"),dest=new File(getFilesDir(),"replay.json");try(FileOutputStream file=new FileOutputStream(tmp)){file.write(ReplayBootstrap.encode(replay));file.getFD().sync();}if(!tmp.renameTo(dest))throw new IOException("回放输入保存未完成");}runOnUiThread(()->{if(!closed){try{startActivity(new Intent().setClassName(this,"com.supercell.clashroyale.GameApp"));handedOff=true;finish();}catch(Exception e){ReplayBootstrap.recordFailure(this,"engine_start_failed","handoff",e);ReplayBootstrap.close(this);}}});}catch(Exception e){ReplayBootstrap.recordFailure(this,"input_prepare_failed","input_prepare",e);runOnUiThread(()->{if(!closed)new AlertDialog.Builder(this).setTitle("回放未启动").setMessage(e.getMessage()).setPositiveButton("返回",(d,w)->ReplayBootstrap.close(this)).show();});}},"replay-open").start();}
 public void onDestroy(){closed=true;if(!handedOff&&!isChangingConfigurations())ReplayBootstrap.finishProcess(this);super.onDestroy();}
}
